{"command":"cd ~/.dsh/sessions && node -e "
const fs=require('fs'), path=require('path'), zlib=require('node:zlib');
const base=process.cwd();
const MAGIC=Buffer.from([0x28,0xB5,0x2F,0xFD]);
function frames(buf){
  const out=[]; let i=0;
  while(true){
    const idx=buf.indexOf(MAGIC,i);
    if(idx<0) break;
    let j=buf.indexOf(MAGIC,idx+4);
    if(j<0) j=buf.length;
    out.push(buf.subarray(idx,j)); i=j;
  }
  return out;
}
let n=0;
for(const d of fs.readdirSync(base)){
  if(!d.includes('live-home-workspace')&&!d.includes('q23-r0-home-workspace')) continue;
  for(const s of fs.readdirSync(path.join(base,d))){
    const f=path.join(base,d,s,'session.v4.jsonl.zstd');
    if(!fs.existsSync(f)) continue;
    const buf=fs.readFileSync(f);
    const parts=frames(buf).map(fr=>{try{return zlib.zstdDecompressSync(fr)}catch(e){return Buffer.from('')}});
    fs.mkdirSync('/tmp/sess3',{recursive:true});
    fs.writeFileSync('/tmp/sess3/'+s+'.jsonl', Buffer.concat(parts));
    n++;
  }
}
console.log('done',n);
